package com.papaya.claims.claim.domain;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;

/** Immutable JSON object values. Nested maps and lists are defensively copied. */
public record ClaimFacts(Map<String, Object> values) {
    public ClaimFacts {
        Objects.requireNonNull(values, "values");
        values = immutableMap(values);
    }

    private static Map<String, Object> immutableMap(Map<?, ?> source) {
        Map<String, Object> copy = new LinkedHashMap<>();
        source.forEach((key, value) -> {
            if (!(key instanceof String stringKey) || stringKey.isBlank()) {
                throw new IllegalArgumentException("Fact keys must be nonblank strings");
            }
            copy.put(stringKey, immutableValue(value));
        });
        return Collections.unmodifiableMap(copy);
    }

    private static Object immutableValue(Object value) {
        if (value == null || value instanceof String || value instanceof Boolean || value instanceof BigDecimal
                || value instanceof Integer || value instanceof Long) return value;
        if (value instanceof Number number) return new BigDecimal(number.toString());
        if (value instanceof Map<?, ?> map) return immutableMap(map);
        if (value instanceof List<?> list) {
            List<Object> copy = new ArrayList<>(list.size());
            list.forEach(item -> copy.add(immutableValue(item)));
            return Collections.unmodifiableList(copy);
        }
        throw new IllegalArgumentException("Unsupported claim fact value type: " + value.getClass().getName());
    }
}
package com.papaya.claims.claim.domain;

import java.time.Instant;
import java.util.Objects;
import java.util.Optional;

/** Trusted workflow evidence persisted alongside a claim. */
public record ClaimWorkflowData(int informationRequests, Instant lastInformationRequestedAt,
        Instant lastInformationReceivedAt, Instant assessmentStartedAt, Instant rejectedAt,
        Instant memberAcknowledgedRejectionAt) {
    public ClaimWorkflowData {
        if (informationRequests < 0) throw new IllegalArgumentException("informationRequests cannot be negative");
        lastInformationRequestedAt = micros(lastInformationRequestedAt);
        lastInformationReceivedAt = micros(lastInformationReceivedAt);
        assessmentStartedAt = micros(assessmentStartedAt);
        rejectedAt = micros(rejectedAt);
        memberAcknowledgedRejectionAt = micros(memberAcknowledgedRejectionAt);
    }

    public static ClaimWorkflowData empty() { return new ClaimWorkflowData(0, null, null, null, null, null); }
    public Optional<Instant> lastRequested() { return Optional.ofNullable(lastInformationRequestedAt); }
    private static Instant micros(Instant value) { return value == null ? null : value.truncatedTo(java.time.temporal.ChronoUnit.MICROS); }
}
package com.papaya.claims.claim.domain;

import java.time.Instant;
import java.util.Objects;
import java.util.UUID;

/** Safe operational audit metadata; request content and secrets are intentionally excluded. */
public record SystemOperationAuditRecord(UUID id, String action, String resource, String resourceId,
        String actorId, String correlationId, String outcome, String errorType, Instant occurredAt) {
    public SystemOperationAuditRecord {
        Objects.requireNonNull(id, "id");
        require(action, "action"); require(resource, "resource"); require(actorId, "actorId");
        Objects.requireNonNull(correlationId, "correlationId"); require(outcome, "outcome");
        Objects.requireNonNull(occurredAt, "occurredAt");
    }
    private static void require(String value, String field) {
        if (value == null || value.isBlank()) throw new IllegalArgumentException(field + " is required");
    }
}
package com.papaya.claims.claim.domain.persistence;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.papaya.claims.claim.domain.*;
import java.util.Map;

final class PersistenceMapping {
    private static final TypeReference<Map<String,Object>> MAP = new TypeReference<>() {};
    private PersistenceMapping() {}
    static String json(ObjectMapper mapper, Object value) {
        try { return mapper.writeValueAsString(value); }
        catch (JsonProcessingException e) { throw new IllegalArgumentException("Could not encode persistence JSON", e); }
    }
    static Map<String,Object> map(ObjectMapper mapper, String value) {
        try { return mapper.readValue(value, MAP); }
        catch (JsonProcessingException e) { throw new IllegalStateException("Could not decode persisted JSON", e); }
    }
    static ClaimAggregate aggregate(ObjectMapper mapper, ClaimRow r) {
        Claim c = new Claim(r.id, r.memberId, r.state, r.policyLimit, r.currency, r.version,
                new ClaimFacts(map(mapper, r.factsJson)), r.createdAt, r.updatedAt);
        return new ClaimAggregate(c, new ClaimWorkflowData(r.informationRequests, r.lastInformationRequestedAt,
                r.lastInformationReceivedAt, r.assessmentStartedAt, r.rejectedAt, r.memberAcknowledgedRejectionAt));
    }
    static ClaimRow row(ObjectMapper mapper, ClaimAggregate a) {
        Claim c = a.claim(); ClaimWorkflowData w = a.workflow(); ClaimRow r = new ClaimRow();
        r.id=c.id(); r.memberId=c.memberId(); r.state=c.state(); r.policyLimit=c.policyLimit(); r.currency=c.currency();
        r.version=c.version(); r.factsJson=json(mapper,c.facts().values()); r.informationRequests=w.informationRequests();
        r.lastInformationRequestedAt=w.lastInformationRequestedAt(); r.lastInformationReceivedAt=w.lastInformationReceivedAt();
        r.assessmentStartedAt=w.assessmentStartedAt(); r.rejectedAt=w.rejectedAt();
        r.memberAcknowledgedRejectionAt=w.memberAcknowledgedRejectionAt(); r.createdAt=c.createdAt(); r.updatedAt=c.updatedAt(); return r;
    }
}
